  "onboarding.tour.import.button.body": "PDF、EPUB、网页文章、YouTube 视频、播客——它们都会出现在这里。点击导入以打开文件，或使用工具栏上的 URL 导入来添加任何带链接的内容。",
  "onboarding.tour.import.button.title": "导入文档",
  "onboarding.tour.import.grid.body": "导入的文档会显示在这里。打开任意一个即可开始阅读并创建摘录。",
  "onboarding.tour.import.grid.title": "你的书库",
  "onboarding.tour.import.url.body": "工具栏的“导入 URL”可抓取网页文章、arXiv 论文和 YouTube 转录。命令面板（Ctrl+K / Cmd+K）也能完成同样操作，无需离开键盘。",
  "onboarding.tour.import.url.title": "从 URL 导入",
  "onboarding.tour.knowledge.analytics.body": "查看你的保持率、复习活动和随时间的进度。数据会随你的复习而更新。",
  "onboarding.tour.knowledge.analytics.title": "统计分析",
  "onboarding.tour.knowledge.sphere.body": "一份展示文档与摘录关联的空间地图。缩小视图即可看到你所学内容的整体形态。",
  "onboarding.tour.knowledge.sphere.title": "知识宇宙",
  "onboarding.tour.make.settings.body": "设置中包含主题、键盘快捷键、同步、集成、AI 提供商和学习算法。所有自定义应用的内容都在这里。",
  "onboarding.tour.make.settings.title": "个性化定制",
  "onboarding.tour.make.workspace.body": "工作区可将你的书库划分为不同情境——研究、个人、副业项目。可在工具栏上切换。",
  "onboarding.tour.make.workspace.title": "工作区",
  "onboarding.tour.queue.controls.body": "开启一次最佳复习会话，在阅读、计划表和复习模式之间切换队列，或手动浏览。队列是驱动你每日循环的核心所在。",
  "onboarding.tour.queue.controls.title": "队列控制",
  "onboarding.tour.queue.nav.body": "队列收纳你添加的所有内容——待读文档、待学摘录。从导航栏打开它，可查看下一个到期项或随机挑选。",
  "onboarding.tour.queue.nav.title": "队列",
  "onboarding.tour.read.extract.body": "在阅读器中选中一段文字即可将其提取为摘录——笔记、闪卡或填空题。摘录会成为复习调度器学习的单元。",
  "onboarding.tour.read.extract.title": "创建摘录",
  "onboarding.tour.read.extracts.body": "你创建的每条摘录都会汇集于此，并附上来源，便于随时回到原始语境。",
  "onboarding.tour.read.extracts.title": "摘录面板",
  "onboarding.tour.read.reader.body": "每份文档都会在专属标签页中打开，配备为长篇阅读优化的阅读器。同一界面还提供接下来要介绍的摘录工具。",
  "onboarding.tour.read.reader.title": "在阅读器中阅读",
  "onboarding.tour.review.algorithm.body": "Plethora 内置多种调度器——FSRS-6、Plethora Adaptive、Plethora Precision 和 Plethora Classic。可在“设置 → 学习”中选择适合你的那一种。",
  "onboarding.tour.review.algorithm.title": "选择你的算法",
  "onboarding.tour.review.grading.body": "每张卡片复习后，选择符合你回忆程度的评分。调度器会据此决定何时再次显示该卡片——回忆越好，间隔越长。",
  "onboarding.tour.review.grading.title": "评分控制",
  "onboarding.tour.review.nav.body": "当摘录到期时，复习会话会带你逐一过一遍，并询问你对每一条的记忆程度。你的回答将训练间隔重复调度器。",
  "onboarding.tour.review.nav.title": "复习会话",
  "onboarding.tour.welcome.body": "这是一次关于“导入 → 阅读 → 摘录 → 复习”循环的快速导览。大约只需两分钟，你可以随时离开——按 Esc 或点击别处可暂停，下次会从你离开的地方继续。",
  "onboarding.tour.welcome.title": "欢迎使用 Plethora",
